import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const p=JSON.parse('{"title":"自定义组件深度解析","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/自定义组件深度解析.md","filePath":"脚本系统/专题研究/自定义组件深度解析.md","lastUpdated":1777893104000}'),h={name:"脚本系统/专题研究/自定义组件深度解析.md"};function d(n,l,o,c,t,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="自定义组件深度解析" tabindex="-1">自定义组件深度解析 <a class="header-anchor" href="#自定义组件深度解析" aria-label="Permalink to “自定义组件深度解析”">​</a></h1><ul><li>分类：脚本</li><li>子系统：自定义组件 / 属性 / 指令 / 触发时机 / 组件复用</li><li>关键词标签：自定义组件, 属性, 指令, 触发时机, 组件复用, 模块化, 状态记录</li><li>来源类型：脚本界面截图 + 官方教程主题归纳</li><li>证据等级：截图直接证据 + 教程交叉归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code>, <code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>来源截图编号：215530, 215340, 110140, 110143</li><li>对应 OCR 文档：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code>, <code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li></ul><p>本文件基于 <code>资料/基础写脚本界面截图/</code> 与官方教程中的自定义组件说明整理，目标是把“自定义组件”从简单索引提升为更适合学习与检索的结构化知识。</p><h2 id="_1-自定义组件是什么" tabindex="-1">1. 自定义组件是什么 <a class="header-anchor" href="#_1-自定义组件是什么" aria-label="Permalink to “1. 自定义组件是什么”">​</a></h2><p>从教程截图 <code>Screenshot_20260418_105850.jpg</code> 可知：</p><ul><li>自定义组件是创作者自己编写的组件。</li><li>可以自行定义组件内部的： <ul><li>属性</li><li>指令</li><li>触发时机</li></ul></li><li>作用是给物体补充官方组件之外的特定能力。</li></ul><h3 id="教程中的核心观点" tabindex="-1">教程中的核心观点 <a class="header-anchor" href="#教程中的核心观点" aria-label="Permalink to “教程中的核心观点”">​</a></h3><p>官方内置组件是固定的，因此：</p><ul><li>可记录的状态有限</li><li>可直接实现的功能有限</li></ul><p>而自定义组件可以弥补这一点，让创作者把某种功能打包成一个可复用模块。</p><hr><h2 id="_2-自定义组件的三大核心元素" tabindex="-1">2. 自定义组件的三大核心元素 <a class="header-anchor" href="#_2-自定义组件的三大核心元素" aria-label="Permalink to “2. 自定义组件的三大核心元素”">​</a></h2><p>从脚本界面截图中可稳定确认：</p><ul><li>属性</li><li>指令</li><li>触发时机</li></ul><h3 id="_2-1-属性" tabindex="-1">2.1 属性 <a class="header-anchor" href="#_2-1-属性" aria-label="Permalink to “2.1 属性”">​</a></h3><p>属性用于保存状态或参数，例如：</p><ul><li>数字型属性</li><li>文本型属性</li><li>未来可能还有真假值、对象引用等</li></ul><h3 id="_2-2-指令" tabindex="-1">2.2 指令 <a class="header-anchor" href="#_2-2-指令" aria-label="Permalink to “2.2 指令”">​</a></h3><p>指令可以理解为“组件暴露出来的可调用动作入口”。 例如：</p><ul><li>指令1</li><li>指令2</li></ul><h3 id="_2-3-触发时机" tabindex="-1">2.3 触发时机 <a class="header-anchor" href="#_2-3-触发时机" aria-label="Permalink to “2.3 触发时机”">​</a></h3><p>触发时机可以理解为“事件入口”或“自动响应入口”。 它让组件不仅能被主动调用，也能在特定时机自己触发逻辑。</p><hr><h2 id="_3-为什么自定义组件重要" tabindex="-1">3. 为什么自定义组件重要 <a class="header-anchor" href="#_3-为什么自定义组件重要" aria-label="Permalink to “3. 为什么自定义组件重要”">​</a></h2><p>结合教程原文，可以归纳出两个核心价值：</p><h3 id="_3-1-满足特定需求" tabindex="-1">3.1 满足特定需求 <a class="header-anchor" href="#_3-1-满足特定需求" aria-label="Permalink to “3.1 满足特定需求”">​</a></h3><p>例如做一棵可以互动的树，可能需要记录：</p><ul><li>当前状态（被砍倒 / 未被砍倒）</li><li>再次生长时间</li><li>掉落木头数量</li><li>是否可互动</li></ul><p>如果内置组件无法完整表示这些逻辑，就需要自定义组件。</p><h3 id="_3-2-提高复用性" tabindex="-1">3.2 提高复用性 <a class="header-anchor" href="#_3-2-提高复用性" aria-label="Permalink to “3.2 提高复用性”">​</a></h3><p>当某个功能被封装为组件后：</p><ul><li>想让另一个物体拥有同样能力</li><li>只需挂载同一个组件</li></ul><p>这说明自定义组件本质上是一种“功能模块复用机制”。</p><hr><h2 id="_4-自定义组件的内部执行模型" tabindex="-1">4. 自定义组件的内部执行模型 <a class="header-anchor" href="#_4-自定义组件的内部执行模型" aria-label="Permalink to “4. 自定义组件的内部执行模型”">​</a></h2><p>结合脚本截图可推断，自定义组件至少具备以下模型：</p><h3 id="数据层" tabindex="-1">数据层 <a class="header-anchor" href="#数据层" aria-label="Permalink to “数据层”">​</a></h3><ul><li>保存组件属性</li><li>记录状态</li><li>作为脚本读写目标</li></ul><h3 id="行为层" tabindex="-1">行为层 <a class="header-anchor" href="#行为层" aria-label="Permalink to “行为层”">​</a></h3><ul><li>通过指令提供动作接口</li><li>通过触发时机响应事件</li></ul><h3 id="脚本层" tabindex="-1">脚本层 <a class="header-anchor" href="#脚本层" aria-label="Permalink to “脚本层”">​</a></h3><ul><li>在 <code>当执行“某指令”时</code> 内编写积木逻辑</li><li>可调用基础、系统、自身、地图等不同作用域脚本块</li></ul><h3 id="组件化意义" tabindex="-1">组件化意义 <a class="header-anchor" href="#组件化意义" aria-label="Permalink to “组件化意义”">​</a></h3><p>这说明自定义组件不是单纯的数据配置，而是：</p><ul><li>有数据</li><li>有入口</li><li>有事件</li><li>有脚本</li></ul><p>它更接近一个“小型逻辑模块”。</p><hr><h2 id="_5-已确认的脚本作用域" tabindex="-1">5. 已确认的脚本作用域 <a class="header-anchor" href="#_5-已确认的脚本作用域" aria-label="Permalink to “5. 已确认的脚本作用域”">​</a></h2><p>从截图 <code>Screenshot_20260417_215355.jpg</code> 可以确认，在自定义组件指令脚本中至少可操作：</p><ul><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li></ul><h3 id="对应意义" tabindex="-1">对应意义 <a class="header-anchor" href="#对应意义" aria-label="Permalink to “对应意义”">​</a></h3><ul><li>局部变量：当前执行流程中的临时数据</li><li>自身属性：组件或物体本体状态</li><li>当前地图属性：场景级共享数据</li><li>系统属性：更全局的共享数据</li></ul><h3 id="设计价值" tabindex="-1">设计价值 <a class="header-anchor" href="#设计价值" aria-label="Permalink to “设计价值”">​</a></h3><p>这种多层作用域让自定义组件既能封装自己内部逻辑，也能与地图逻辑和全局逻辑联动。</p><hr><h2 id="_6-自定义组件与官方组件的关系" tabindex="-1">6. 自定义组件与官方组件的关系 <a class="header-anchor" href="#_6-自定义组件与官方组件的关系" aria-label="Permalink to “6. 自定义组件与官方组件的关系”">​</a></h2><h3 id="官方组件" tabindex="-1">官方组件 <a class="header-anchor" href="#官方组件" aria-label="Permalink to “官方组件”">​</a></h3><p>优点：</p><ul><li>功能稳定</li><li>结构标准</li><li>易上手</li></ul><p>限制：</p><ul><li>功能边界固定</li><li>针对特定复杂需求时不够灵活</li></ul><h3 id="自定义组件" tabindex="-1">自定义组件 <a class="header-anchor" href="#自定义组件" aria-label="Permalink to “自定义组件”">​</a></h3><p>优点：</p><ul><li>可按玩法自由定义</li><li>可封装复杂状态</li><li>可做项目内复用</li></ul><p>限制：</p><ul><li>需要自己设计结构</li><li>需要自己维护变量、指令和触发时机</li><li>如果命名和职责不清，后期会很乱</li></ul><hr><h2 id="_7-设计自定义组件时的建议" tabindex="-1">7. 设计自定义组件时的建议 <a class="header-anchor" href="#_7-设计自定义组件时的建议" aria-label="Permalink to “7. 设计自定义组件时的建议”">​</a></h2><h3 id="_7-1-先设计-属性-再写脚本" tabindex="-1">7.1 先设计“属性”再写脚本 <a class="header-anchor" href="#_7-1-先设计-属性-再写脚本" aria-label="Permalink to “7.1 先设计“属性”再写脚本”">​</a></h3><p>建议先明确：</p><ul><li>这个组件要保存哪些状态？</li><li>哪些值需要外部可配？</li><li>哪些值是内部运行态？</li></ul><h3 id="_7-2-指令命名要明确" tabindex="-1">7.2 指令命名要明确 <a class="header-anchor" href="#_7-2-指令命名要明确" aria-label="Permalink to “7.2 指令命名要明确”">​</a></h3><p>例如比起“指令1”，更推荐：</p><ul><li>开始生长</li><li>掉落资源</li><li>切换状态</li><li>打开界面</li></ul><h3 id="_7-3-触发时机尽量只做入口" tabindex="-1">7.3 触发时机尽量只做入口 <a class="header-anchor" href="#_7-3-触发时机尽量只做入口" aria-label="Permalink to “7.3 触发时机尽量只做入口”">​</a></h3><p>复杂逻辑建议放到独立指令中，触发时机只负责：</p><ul><li>接到事件</li><li>调用对应指令</li></ul><p>这样更利于维护。</p><h3 id="_7-4-把-通用功能-做成组件-而不是复制脚本" tabindex="-1">7.4 把“通用功能”做成组件，而不是复制脚本 <a class="header-anchor" href="#_7-4-把-通用功能-做成组件-而不是复制脚本" aria-label="Permalink to “7.4 把“通用功能”做成组件，而不是复制脚本”">​</a></h3><p>如果多个物体都要实现同类功能：</p><ul><li>不要每个物体都重新写一遍脚本</li><li>优先抽成一个自定义组件</li></ul><hr><h2 id="_8-自定义组件的典型适用场景" tabindex="-1">8. 自定义组件的典型适用场景 <a class="header-anchor" href="#_8-自定义组件的典型适用场景" aria-label="Permalink to “8. 自定义组件的典型适用场景”">​</a></h2><ul><li>可成长植物 / 树木</li><li>机关门 / 开关逻辑</li><li>任务状态机</li><li>物体专属交互系统</li><li>自定义 UI 交互模块</li><li>特殊武器附加行为</li><li>多阶段 Boss 机制</li></ul><hr><h2 id="_9-适合-ai-rag-的关键词" tabindex="-1">9. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_9-适合-ai-rag-的关键词" aria-label="Permalink to “9. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>自定义组件</li><li>属性</li><li>指令</li><li>触发时机</li><li>组件复用</li><li>自定义逻辑</li><li>组件化</li><li>模块化</li><li>状态记录</li><li>行为封装</li><li>当执行某指令时</li><li>局部变量</li><li>自身属性</li><li>地图属性</li><li>系统属性</li></ul><hr><h2 id="_10-后续可继续拆分的子主题" tabindex="-1">10. 后续可继续拆分的子主题 <a class="header-anchor" href="#_10-后续可继续拆分的子主题" aria-label="Permalink to “10. 后续可继续拆分的子主题”">​</a></h2><ol><li>自定义组件命名规范建议</li><li>自定义组件中的变量作用域详解</li><li>自定义组件与地图广播的配合方式</li><li>自定义组件与 UI 系统的联动模式</li><li>自定义组件在联机中的同步边界</li></ol>',90)])])}const b=i(h,[["render",d]]);export{p as __pageData,b as default};
